mapper.select:
SELECT f.id, f.user_id AS userId, IFNULL(u.real_name, '已注销用户') AS userName, IFNULL(u.avatar, '') AS avatar, f.stall_id AS stallId, s.name AS stallName, f.title, f.content, f.type, f.status, f.reply_content AS replyContent, ru.real_name AS replyUserName, f.reply_time AS replyTime, f.create_time AS createTime FROM feedback f LEFT JOIN sys_user u ON f.user_id = u.id AND u.deleted = 0 LEFT JOIN canteen_stall s ON f.stall_id = s.id AND s.deleted = 0 LEFT JOIN sys_user ru ON f.reply_user_id = ru.id AND ru.deleted = 0 WHERE f.deleted = 0
AND f.user_id = #{userId}
AND f.stall_id = #{query.stallId}
AND f.type = #{query.type}
AND f.status = #{query.status}
AND (f.title LIKE CONCAT('%', #{query.keyword}, '%') OR f.content LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY f.create_time DESC
